const upsertScoringResult = `-- name: UpsertScoringResult :exec
INSERT INTO scoring_results (application_id, score, grade, factors, hard_stops, max_affordable, debt_load, enrichment, metrics)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (application_id) DO UPDATE SET score = EXCLUDED.score, grade = EXCLUDED.grade, factors = EXCLUDED.factors,
  hard_stops = EXCLUDED.hard_stops, max_affordable = EXCLUDED.max_affordable, debt_load = EXCLUDED.debt_load,
  enrichment = EXCLUDED.enrichment, metrics = EXCLUDED.metrics, created_at = now()
`

type UpsertScoringResultParams struct {
	ApplicationID string  `json:"application_id"`
	Score         int32   `json:"score"`
	Grade         string  `json:"grade"`
	Factors       []byte  `json:"factors"`
	HardStops     []byte  `json:"hard_stops"`
	MaxAffordable int64   `json:"max_affordable"`
	DebtLoad      float64 `json:"debt_load"`
	Enrichment    []byte  `json:"enrichment"`
	Metrics       []byte  `json:"metrics"`
}

func (q *Queries) UpsertScoringResult(ctx context.Context, arg UpsertScoringResultParams) error {
	_, err := q.db.Exec(ctx, upsertScoringResult,
		arg.ApplicationID,
		arg.Score,
		arg.Grade,
		arg.Factors,
		arg.HardStops,
		arg.MaxAffordable,
		arg.DebtLoad,
		arg.Enrichment,
		arg.Metrics,
	)
	return err
}
